#include <iostream>
#include <sstream>

int main() {
    // Check default tying of cin
    std::ostream* prevTie = std::cin.tie();
    if (prevTie == &std::cout) {
        std::cout << "cin is tied to cout by default\n";
    }

    // Untie cin using modern C++17 nullptr (legacy used tie(0))
    std::cin.tie(nullptr);
    if (std::cin.tie() == nullptr) {
        std::cout << "cin successfully untied\n";
    }

    // Demonstrate custom tying with string streams
    std::istringstream inStream("100");
    std::ostringstream outStream;

    inStream.tie(&outStream);
    outStream << "Buffered-Message";

    int val = 0;
    inStream >> val; // Triggers automatic flush on outStream

    std::cout << "Read value: " << val << "\n";
    std::cout << "Tied buffer: " << outStream.str() << "\n";

    // Restore cin tie
    std::cin.tie(&std::cout);
    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>

int main() {
    // 1. Unformatted output using write and cascaded put
    char banner[] = "CPP";
    std::cout.write(banner, 3);
    std::cout.put(' ').put('I').put('/').put('O').put('\n');

    // 2. Stream error recovery using fail() and clear()
    std::istringstream stream("invalid 999");
    int number = 0;
    stream >> number; // Fails to convert string to int

    if (stream.fail()) {
        std::cout << "Stream failed as expected\n";
        stream.clear(); // Clear failbit
        std::string token;
        stream >> token;  // Extract invalid token
        stream >> number; // Read next integer correctly
        std::cout << "Recovered: " << token << ", number: " << number << "\n";
    }

    // 3. Formatting manipulators
    std::cout << std::internal << std::showbase << std::hex << std::setfill('*')
              << std::setw(8) << 255 << std::dec << "\n";

    return 0;
}
